fn frame(t: i32) {
    if host::display::state_get(1) == 0 {
        host::display::state_set(1, 1);
        host::display::state_set(0, 50);
    }
    let mut c: i32 = host::display::state_get(0);
    let down: i32 = host::display::pointer_down();
    if down == 1 {
        if t % 2 == 0 && c < 100 { c = c + 1; }
    } else {
        if t % 5 == 0 && c > 0 { c = c - 1; }
    }
    host::display::state_set(0, c);
    host::display::clear(0x101010);
    let col: i32 = if c < 30 { 0xff3030 } else { if c < 70 { 0xffcc00 } else { 0x00cc55 } };
    let bx: i32 = 100;
    let by: i32 = 90;
    host::display::fill_rect(bx - 4, by - 4, 108, 248, 0x505050);
    host::display::fill_rect(bx, by, 100, 240, 0x000000);
    host::display::fill_rect(bx + 30, by - 16, 40, 12, 0x505050);
    let mut i: i32 = 0;
    while i < 10 {
        if c > i * 10 {
            host::display::fill_rect(bx + 6, by + 240 - (i + 1) * 24 + 3, 88, 18, col);
        }
        i = i + 1;
    }
    host::display::draw_number(bx, by + 250, c, col, 3);
    host::display::draw_string(bx, by + 284, "HOLD TO CHARGE", 0x808080, 1);
    host::display::present();
}
